int feeder_log_header(char *buf, size_t size)
{
    return snprintf(buf, size, "feed_asked,feed_portions,fed_recently,plan");
}

int feeder_log_row(const feeder_state_t *s, char *buf, size_t size)
{
    const tlg_agent_t *a = &s->agent;
    int n = snprintf(buf, size, "%s,%s,%s,", V_FEED_ASKED[s->in.feed_asked], V_FEED_PORTIONS[s->in.feed_portions], V_FED_RECENTLY[s->in.fed_recently]);
    if (n < 0 || (size_t)n >= size) return n;
    if (!a->acted_ok || a->plan_len == 0)
        return n + snprintf(buf + n, size - (size_t)n, "%s", a->acted_ok ? "nothing" : "-");
    for (int i = 0; i < a->plan_len; i++) {
        int w = snprintf(buf + n, size - (size_t)n, "%s%s", i ? "+" : "", feeder_domain.actions[a->plan[i]].name);
        if (w < 0 || (size_t)(n + w) >= size) return n + w;
        n += w;
    }
    return n;
}

int feeder_status_json(const feeder_state_t *s, char *buf, size_t size)
{
    const tlg_agent_t *a = &s->agent;
    int n = snprintf(buf, size, "{\"feed_asked\":\"%s\",\"feed_portions\":\"%s\",\"fed_recently\":\"%s\",\"plan\":\"", V_FEED_ASKED[s->in.feed_asked], V_FEED_PORTIONS[s->in.feed_portions], V_FED_RECENTLY[s->in.fed_recently]);
    if (n < 0 || (size_t)n >= size) return -1;
    if (!a->acted_ok || a->plan_len == 0)
        n += snprintf(buf + n, size - (size_t)n, "%s", a->acted_ok ? "nothing" : "-");
    for (int i = 0; a->acted_ok && i < a->plan_len && (size_t)n < size; i++)
        n += snprintf(buf + n, size - (size_t)n, "%s%s", i ? " " : "", feeder_domain.actions[a->plan[i]].name);
    if ((size_t)n >= size) return -1;
    n += snprintf(buf + n, size - (size_t)n, "\"}");
    return (size_t)n < size ? n : -1;
}

